CREATE TABLE payments AS
  SELECT g AS id, 'card-' || (g % 5000) AS card, (g % 997) * 100 AS amount_cents
  FROM generate_series(1, 200000) g;
VACUUM payments;
SELECT pg_relation_size('payments') / 8192 AS pages;

SELECT buffers_evicted FROM pg_buffercache_evict_relation('payments');
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT count(*) FROM payments;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT count(*) FROM payments;

BEGIN;
DECLARE c CURSOR FOR SELECT * FROM payments;
FETCH 3 FROM c;
SELECT relblocknumber, pinning_backends FROM pg_buffercache
WHERE relfilenode = pg_relation_filenode('payments') AND pinning_backends > 0;

MOVE 300 IN c;
SELECT relblocknumber, pinning_backends FROM pg_buffercache
WHERE relfilenode = pg_relation_filenode('payments') AND pinning_backends > 0;
COMMIT;

SELECT count(*) AS pinned FROM pg_buffercache
WHERE relfilenode = pg_relation_filenode('payments') AND pinning_backends > 0;

SELECT usagecount, count(*) AS buffers FROM pg_buffercache
WHERE relfilenode = pg_relation_filenode('payments') GROUP BY 1 ORDER BY 1;

SELECT count(*) FROM payments \g /dev/null
SELECT usagecount, count(*) AS buffers FROM pg_buffercache
WHERE relfilenode = pg_relation_filenode('payments') GROUP BY 1 ORDER BY 1;

-- four more times, then look again
SELECT count(*) FROM payments \g /dev/null
SELECT count(*) FROM payments \g /dev/null
SELECT count(*) FROM payments \g /dev/null
SELECT count(*) FROM payments \g /dev/null
SELECT usagecount, count(*) AS buffers FROM pg_buffercache
WHERE relfilenode = pg_relation_filenode('payments') GROUP BY 1 ORDER BY 1;

SELECT * FROM pg_buffercache_usage_counts();

CREATE TABLE settlements AS
  SELECT g AS id, 'batch-' || (g % 365) AS batch, g % 100000 AS amount_cents
  FROM generate_series(1, 1200000) g;
VACUUM settlements;
SELECT pg_size_pretty(pg_relation_size('settlements')) AS size, pg_relation_size('settlements') / 8192 AS pages;
SELECT buffers_evicted FROM pg_buffercache_evict_relation('settlements');

SET max_parallel_workers_per_gather = 0;
SELECT count(*) FROM payments;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT count(*) FROM settlements;

SELECT c.relname, count(b.bufferid) AS cached_pages
FROM pg_class c
LEFT JOIN pg_buffercache b ON b.relfilenode = pg_relation_filenode(c.oid) AND b.relforknumber = 0
WHERE c.relname IN ('payments', 'settlements')
GROUP BY c.relname ORDER BY c.relname;

