val lru = LinkedHashMap<Int, Frame>(16, 0.75f, true)

fun hit(pageId: Int): Frame? = synchronized(lru) {
    lru[pageId]                      // a write to the shared list on every read
}

fun victim(): Frame = synchronized(lru) {
    lru.values.first { it.pinCount == 0 }   // least recently used, unpinned
}

