fun victim(): Frame {
    var tries = frames.size                  // pinned frames we may pass in a row
    while (true) {
        val f = frames[hand]
        hand = (hand + 1) % frames.size      // always move on, even past the victim
        if (f.pinCount == 0) {
            if (f.usageCount == 0) return f  // unpinned and out of credit: evict it
            f.usageCount--                   // second chance, one credit less
            tries = frames.size
        } else if (--tries == 0) {
            throw NoFreeFrameException()     // a whole lap of pinned frames
        }
    }
}

// A pinned page is in use right now, so it is the opposite of a good victim.
// Taking its credits away would make it leave sooner the moment it is unpinned.
